*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-primary:        #4f46e5;  /* darkened from #6366f1 — was 4.47:1 on white, now 6.29:1 */
  --clr-primary-dark:   #4338ca;  /* darkened from #4f46e5 to maintain a distinct hover */
  --clr-primary-light:  #eef2ff;
  --clr-success:        #16a34a;
  --clr-success-bg:     #f0fdf4;
  --clr-missed-bg:      #fefce8;
  --clr-missed-text:    #92400e;
  --clr-error:          #dc2626;
  --clr-error-bg:       #fef2f2;
  --clr-text:           #0f172a;
  --clr-text-muted:     #64748b;
  --clr-border:         #e2e8f0;
  --clr-bg:             #f1f5f9;
  --clr-card:           #ffffff;
  --radius-lg:          14px;
  --radius-md:          8px;
  --radius-sm:          5px;
  --shadow-sm:          0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md:          0 4px 12px rgba(0,0,0,.10);
  --font:               system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI',
                        Roboto, Helvetica, Arial, sans-serif;
  --transition:         0.15s ease;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--clr-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 600;
  font-family: var(--font);
  text-decoration: none;
  z-index: 200;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Screen-reader only ── */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Base ── */
body {
  font-family: var(--font);
  background: var(--clr-bg);
  color: var(--clr-text);
  min-height: 100vh;
  line-height: 1.6;
}

/* ── Header ── */
.site-header {
  background: var(--clr-card);
  border-bottom: 1px solid var(--clr-border);
  padding: 0 1.5rem;
}
.header-inner {
  max-width: 780px;
  margin: 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.logo { font-size: 1.25rem; }
.logo-text {
  font-size: 1.0625rem;
  font-weight: 800;
  color: var(--clr-primary);
  letter-spacing: -0.02em;
}

/* ── Main layout ── */
main { padding: 2.5rem 1.5rem 5rem; }
.quiz-container { max-width: 680px; margin: 0 auto; }

/* ── Quiz header ── */
.quiz-header { margin-bottom: 2rem; }
.quiz-header h1 {
  font-size: 1.875rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--clr-text);
  margin-bottom: 0.5rem;
}
.quiz-subtitle {
  font-size: 0.9375rem;
  color: var(--clr-text-muted);
}

/* ── Question cards (form-field) ── */
.form-field {
  background: var(--clr-card);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  margin-bottom: 1.25rem;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition);
}
.form-field:focus-within { box-shadow: var(--shadow-md); }

/* ── Fieldset & legend ── */
fieldset { border: none; padding: 0; min-width: 0; }

/* float trick keeps legend full-width inside fieldset */
legend {
  float: left;
  width: 100%;
  padding: 0;
  margin-bottom: 1.125rem;
}
legend + * { clear: both; }

.question-number {
  display: block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--clr-primary);
  margin-bottom: 0.375rem;
}
.question-text {
  display: block;
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--clr-text);
  line-height: 1.45;
}

/* ── Help text ── */
.help-text {
  font-size: 0.8125rem;
  color: var(--clr-text-muted);
  margin-top: -0.625rem;
  margin-bottom: 1.125rem;
  line-height: 1.5;
}

/* ── Options list ── */
.options {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

/* Wrapping label as the clickable row */
.option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: 1.5px solid var(--clr-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  user-select: none;
  transition: border-color var(--transition), background var(--transition);
}
.option:hover {
  border-color: var(--clr-primary);
  background: var(--clr-primary-light);
}

/* Native checkbox styled via appearance:none */
.option input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border: 2px solid #94a3b8;
  border-radius: var(--radius-sm);
  background: #fff;
  position: relative;
  cursor: pointer;
  transition: border-color var(--transition), background var(--transition);
}
.option input[type="checkbox"]:checked {
  background: var(--clr-primary);
  border-color: var(--clr-primary);
}
.option input[type="checkbox"]:checked::after {
  content: '';
  position: absolute;
  top: 1px;
  left: 4px;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}
/* Visible focus ring on the native input */
.option input[type="checkbox"]:focus-visible {
  outline: 3px solid var(--clr-primary);
  outline-offset: 2px;
}

/* Highlight the whole row when checked */
.option:has(input:checked) {
  border-color: var(--clr-primary);
  background: var(--clr-primary-light);
}

.option-label {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--clr-text);
}

/* ── Per-group error ── */
.group-error {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  margin-top: 0.875rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--clr-error);
}
.group-error::before { content: '⚠'; }
.group-error[hidden] { display: none; }

/* ── Submit button ── */
.form-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 1.75rem;
}
.btn-submit {
  background: var(--clr-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  padding: 0.75rem 2.25rem;
  font-size: 0.9375rem;
  font-weight: 700;
  font-family: var(--font);
  cursor: pointer;
  min-height: 44px;
  transition: background var(--transition), transform 0.1s;
}
.btn-submit:hover { background: var(--clr-primary-dark); }
.btn-submit:focus-visible {
  outline: 3px solid var(--clr-primary);
  outline-offset: 3px;
}
.btn-submit:active { transform: scale(0.98); }

/* ── Results section ── */
#results[hidden] { display: none; }

.results-score-card {
  background: var(--clr-card);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  box-shadow: var(--shadow-sm);
  text-align: center;
  margin-bottom: 1.5rem;
}
.results-score {
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--clr-primary);
  line-height: 1;
  letter-spacing: -0.04em;
}
.results-denom { font-size: 1.5rem; color: var(--clr-text-muted); }
.results-label {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--clr-text-muted);
  margin: 0.375rem 0 1rem;
}
.results-message { font-size: 1.0625rem; font-weight: 600; }

/* ── Answer review ── */
.review-heading {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--clr-text-muted);
  margin-bottom: 0.75rem;
}
.review-card {
  background: var(--clr-card);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  margin-bottom: 1rem;
}
.review-question-label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--clr-primary);
  margin-bottom: 0.25rem;
}
.review-question-text {
  font-size: 0.9375rem;
  font-weight: 700;
  color: var(--clr-text);
  margin-bottom: 1rem;
}
.review-options { display: flex; flex-direction: column; gap: 0.4rem; }
.review-option {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
}
.review-option.correct-selected { background: var(--clr-success-bg); color: var(--clr-success); }
.review-option.missed           { background: var(--clr-missed-bg);  color: var(--clr-missed-text); }
.review-option.wrong-selected   { background: var(--clr-error-bg);   color: var(--clr-error); }
.review-option.neutral          { color: var(--clr-text-muted); }
.review-icon { font-size: 0.8125rem; flex-shrink: 0; width: 1rem; text-align: center; }

/* ── Retry button ── */
.btn-retry {
  display: block;
  margin: 1.75rem auto 0;
  background: transparent;
  color: var(--clr-primary);
  border: 2px solid var(--clr-primary);
  border-radius: var(--radius-md);
  padding: 0.625rem 1.75rem;
  font-size: 0.9375rem;
  font-weight: 700;
  font-family: var(--font);
  cursor: pointer;
  min-height: 44px;
  transition: background var(--transition);
}
.btn-retry:hover  { background: var(--clr-primary-light); }
.btn-retry:focus-visible {
  outline: 3px solid var(--clr-primary);
  outline-offset: 3px;
}

/* ── Noscript ── */
.noscript-warning {
  background: var(--clr-error-bg);
  border: 1px solid var(--clr-error);
  color: var(--clr-error);
  padding: 1rem 1.25rem;
  border-radius: var(--radius-md);
  font-weight: 600;
}

/* ── Responsive ── */
@media (max-width: 480px) {
  main { padding: 1.25rem 1rem 3rem; }
  .form-field { padding: 1.25rem 1rem; }
  .quiz-header h1 { font-size: 1.5rem; }
}

/* ── Forced colors (Windows high-contrast) ── */
@media (forced-colors: active) {
  .option { forced-color-adjust: none; border-color: ButtonBorder; }
  .option:hover,
  .option:has(input:checked) { background: Highlight; color: HighlightText; border-color: Highlight; }
  .option input[type="checkbox"] { forced-color-adjust: auto; }
  .btn-submit,
  .btn-retry { forced-color-adjust: none; }
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}
