  user-select: none;
  transition: border-color var(--transition), background var(--transition);
}
.option:hover {
  border-color: var(--clr-primary);
  background: var(--clr-primary-light);
}

/* Native checkbox styled via appearance:none */
.option input[type="checkbox"] {
