}
.group-error::before { content: '⚠'; }
.group-error[hidden] { display: none; }

/* ── Submit button ── */
.form-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 1.75rem;
}
.btn-submit {
  background: var(--clr-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius-md);
  padding: 0.75rem 2.25rem;
  font-size: 0.9375rem;
  font-weight: 700;
  font-family: var(--font);
  cursor: pointer;
  min-height: 44px;
  transition: background var(--transition), transform 0.1s;
}
.btn-submit:hover { background: var(--clr-primary-dark); }
.btn-submit:focus-visible {
  outline: 3px solid var(--clr-primary);
  outline-offset: 3px;
}
.btn-submit:active { transform: scale(0.98); }

/* ── Results section ── */
#results[hidden] { display: none; }

.results-score-card {
  background: var(--clr-card);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  box-shadow: var(--shadow-sm);
  text-align: center;
  margin-bottom: 1.5rem;
}
.results-score {
  font-size: 3.5rem;
  font-weight: 800;
  color: var(--clr-primary);
  line-height: 1;
  letter-spacing: -0.04em;
}
.results-denom { font-size: 1.5rem; color: var(--clr-text-muted); }
.results-label {
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--clr-text-muted);
  margin: 0.375rem 0 1rem;
}
.results-message { font-size: 1.0625rem; font-weight: 600; }

/* ── Answer review ── */
.review-heading {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--clr-text-muted);
  margin-bottom: 0.75rem;
}
.review-card {
  background: var(--clr-card);
  border: 1px solid var(--clr-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  box-shadow: var(--shadow-sm);
  margin-bottom: 1rem;
}
.review-question-label {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--clr-primary);
  margin-bottom: 0.25rem;
}
.review-question-text {
  font-size: 0.9375rem;
  font-weight: 700;
  color: var(--clr-text);
  margin-bottom: 1rem;
}
.review-options { display: flex; flex-direction: column; gap: 0.4rem; }
.review-option {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
}
.review-option.correct-selected { background: var(--clr-success-bg); color: var(--clr-success); }
