*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --clr-primary:        #4f46e5;  /* darkened from #6366f1 — was 4.47:1 on white, now 6.29:1 */
  --clr-primary-dark:   #4338ca;  /* darkened from #4f46e5 to maintain a distinct hover */
  --clr-primary-light:  #eef2ff;
  --clr-success:        #166534;  /* darkened from #16a34a — was 3.15:1 on success-bg, now 6.81:1 */
  --clr-success-bg:     #f0fdf4;
  --clr-missed-bg:      #fefce8;
  --clr-missed-text:    #92400e;
  --clr-error:          #b91c1c;  /* darkened from #dc2626 — was 4.41:1 on error-bg, now 5.91:1 */
  --clr-error-bg:       #fef2f2;
  --clr-text:           #0f172a;
  --clr-text-muted:     #475569;  /* darkened from #64748b — was 4.34:1 on #f1f5f9, now 6.92:1 */
  --clr-border:         #e2e8f0;
  --clr-bg:             #f1f5f9;
  --clr-card:           #ffffff;
  --radius-lg:          14px;
  --radius-md:          8px;
  --radius-sm:          5px;
  --shadow-sm:          0 1px 3px rgba(0,0,0,.08), 0 1px 2px rgba(0,0,0,.04);
  --shadow-md:          0 4px 12px rgba(0,0,0,.10);
  --font:               system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI',
                        Roboto, Helvetica, Arial, sans-serif;
  --transition:         0.15s ease;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--clr-primary);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: 0 0 var(--radius-sm) var(--radius-sm);
  font-weight: 600;
  font-family: var(--font);
  text-decoration: none;
  z-index: 200;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Screen-reader only ── */
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  white-space: nowrap;
  border: 0;
}

/* ── Base ── */
body {
  font-family: var(--font);
  background: var(--clr-bg);
  color: var(--clr-text);
  min-height: 100vh;
  line-height: 1.6;
}

/* ── Header ── */
.site-header {
  background: var(--clr-card);
  border-bottom: 1px solid var(--clr-border);
  padding: 0 1.5rem;
}
.header-inner {
  max-width: 780px;
  margin: 0 auto;
  height: 56px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}
.logo { font-size: 1.25rem; }
.logo-text {
  font-size: 1.0625rem;
  font-weight: 800;
  color: var(--clr-primary);
  letter-spacing: -0.02em;
}

/* ── Main layout ── */
main { padding: 2.5rem 1.5rem 5rem; }
.quiz-container { max-width: 680px; margin: 0 auto; }

/* ── Quiz header ── */
.quiz-header { margin-bottom: 2rem; }
.quiz-header h1 {
  font-size: 1.875rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--clr-text);
  margin-bottom: 0.5rem;
}
.quiz-subtitle {
  font-size: 0.9375rem;
