  border-radius: var(--radius-lg);
  padding: 1.75rem;
  margin-bottom: 1.25rem;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition);
}
.form-field:focus-within { box-shadow: var(--shadow-md); }

/* ── Fieldset & legend ── */
fieldset { border: none; padding: 0; min-width: 0; }

/* float trick keeps legend full-width inside fieldset */
legend {
  float: left;
  width: 100%;
  padding: 0;
  margin-bottom: 1.125rem;
}
legend + * { clear: both; }

.question-number {
  display: block;
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.07em;
