 * quiz.js — Computer Languages Quiz
 *
 * React-style component architecture in vanilla JS.
 * Each component is a pure function that returns a DOM Element.
 * A top-level App object owns state and mounts/unmounts components.
 */

// ── Data ─────────────────────────────────────────────────────────────────────

const QUESTIONS = [
  {
    id: 'q1',
    text: 'Which of the following are statically typed programming languages?',
    helpText: 'Select all that apply — there may be more than one correct answer.',
    options: [
      { value: 'typescript', label: 'TypeScript' },
      { value: 'python',     label: 'Python'     },
      { value: 'java',       label: 'Java'        },
      { value: 'rust',       label: 'Rust'        },
    ],
    correct: new Set(['typescript', 'java', 'rust']),
  },
  {
    id: 'q2',
    text: 'Which of the following languages were originally designed for systems programming?',
    options: [
      { value: 'c',          label: 'C'           },
      { value: 'rust',       label: 'Rust'        },
      { value: 'javascript', label: 'JavaScript'  },
      { value: 'ruby',       label: 'Ruby'        },
    ],
    correct: new Set(['c', 'rust']),
  },
  {
    id: 'q3',
    text: 'Which of the following are primarily functional programming languages?',
    options: [
      { value: 'haskell', label: 'Haskell' },
      { value: 'java',    label: 'Java'    },
      { value: 'erlang',  label: 'Erlang'  },
      { value: 'c',       label: 'C'       },
    ],
    correct: new Set(['haskell', 'erlang']),
  },
];

// ── Helpers ───────────────────────────────────────────────────────────────────

/** Create an element and set properties/attributes declaratively. */
function el(tag, props = {}, ...children) {
  const node = document.createElement(tag);
  for (const [key, val] of Object.entries(props)) {
    if (key === 'className')      node.className = val;
    else if (key === 'htmlFor')   node.htmlFor = val;
    else if (key === 'textContent') node.textContent = val;
    else if (key === 'hidden')    node.hidden = val;
    else                          node.setAttribute(key, val);
  }
  for (const child of children) {
    if (child == null) continue;
    node.appendChild(typeof child === 'string' ? document.createTextNode(child) : child);
  }
  return node;
}

/** Announce a message to screen readers via the live region. */
function announce(msg) {
  const region = document.getElementById('status-region');
  region.textContent = '';
  // force a DOM update so the new content triggers the live region
  requestAnimationFrame(() => { region.textContent = msg; });
}

function scoreMessage(score, total) {
  if (score === total)         return '🎉 Perfect score! You\'re a true language expert.';
  if (score >= total * 2 / 3) return '👍 Great work! You know your languages well.';
  if (score >= total / 3)     return '📚 Good start — keep studying to level up.';
  return '💡 Lots to learn — the world of languages is wide!';
}

// ── Components ────────────────────────────────────────────────────────────────

/**
 * CheckboxOption — a single labeled checkbox row.
 * @returns {HTMLLabelElement}
 */
function CheckboxOption({ questionId, value, label }) {
  const inputId = `${questionId}-${value}`;

  const input = el('input', {
    type:  'checkbox',
    id:    inputId,
    name:  questionId,
    value: value,
  });

  const span = el('span', { className: 'option-label' }, label);

  const labelEl = el('label', { className: 'option', htmlFor: inputId },
    input, span
  );

  return labelEl;
}

/**
 * QuestionCard — fieldset with legend, optional help text, checkboxes, and
 * an initially-hidden error paragraph.
 * @returns {HTMLDivElement} — the .form-field wrapper
 */
function QuestionCard({ question, index, total }) {
  const helpId  = question.helpText ? `${question.id}-help` : null;
  const errorId = `${question.id}-error`;

  // Build fieldset aria-describedby: help (if any) + error
  const describedBy = [helpId, errorId].filter(Boolean).join(' ');

  const fieldset = el('fieldset', { 'aria-describedby': describedBy });

  // Legend
  const numSpan  = el('span', { className: 'question-number' },
    `Question ${index + 1} of ${total}`
  );
  const textSpan = el('span', { className: 'question-text' }, question.text);
  const legend   = el('legend', {});
  legend.append(numSpan, textSpan);
  fieldset.appendChild(legend);

  // Optional help text (only Q1)
  if (question.helpText) {
    fieldset.appendChild(
      el('p', { className: 'help-text', id: helpId }, question.helpText)
    );
  }

  // Checkbox options
  const optionsDiv = el('div', { className: 'options' });
  for (const opt of question.options) {
    optionsDiv.appendChild(CheckboxOption({ questionId: question.id, ...opt }));
  }
  fieldset.appendChild(optionsDiv);

  // Hidden error paragraph (always in DOM so aria-describedby resolves)
  fieldset.appendChild(
    el('p', { className: 'group-error', id: errorId, hidden: true, role: 'alert' },
      'Error: Please select at least one answer to continue.'
    )
  );

  return el('div', { className: 'form-field', id: `field-${question.id}` }, fieldset);
}

/**
 * QuizForm — the <form> containing all question cards and the submit button.
 * @returns {HTMLFormElement}
 */
function QuizForm({ questions, onSubmit }) {
  const form = el('form', { id: 'quiz-form', novalidate: '' });
  form.setAttribute('novalidate', '');

  for (let i = 0; i < questions.length; i++) {
    form.appendChild(QuestionCard({ question: questions[i], index: i, total: questions.length }));
  }

  const submitBtn = el('button', { type: 'submit', className: 'btn-submit' }, 'Submit Quiz');
  form.appendChild(el('div', { className: 'form-actions' }, submitBtn));

  form.addEventListener('submit', onSubmit);
  return form;
}

/**
 * ReviewOption — a single row in the post-submit answer review.
 * @returns {HTMLDivElement}
 */
function ReviewOption({ label, state }) {
  const icons = { 'correct-selected': '✓', missed: '○', 'wrong-selected': '✗', neutral: '' };
  const icon  = el('span', { className: 'review-icon', 'aria-hidden': 'true' }, icons[state] ?? '');
  return el('div', { className: `review-option ${state}` }, icon, label);
}

/**
 * ReviewCard — shows one question with per-option correct/incorrect feedback.
 * @returns {HTMLDivElement}
 */
function ReviewCard({ question, index, total, selected }) {
  const card = el('div', { className: 'review-card' });

  card.appendChild(el('p', { className: 'review-question-label' }, `Question ${index + 1} of ${total}`));
  card.appendChild(el('p', { className: 'review-question-text' }, question.text));

  const optionsDiv = el('div', { className: 'review-options' });

  for (const opt of question.options) {
    const isCorrect  = question.correct.has(opt.value);
    const isSelected = selected.has(opt.value);

    let state;
    if (isCorrect && isSelected)   state = 'correct-selected';
    else if (isCorrect && !isSelected) state = 'missed';
    else if (!isCorrect && isSelected) state = 'wrong-selected';
    else                               state = 'neutral';

    optionsDiv.appendChild(ReviewOption({ label: opt.label, state }));
  }

  card.appendChild(optionsDiv);
  return card;
}

/**
 * ResultsPanel — score summary + per-question review + retry button.
 * @returns {HTMLElement}
 */
function ResultsPanel({ questions, answers, onRetry }) {
  const section = el('section', { id: 'results' });
  section.setAttribute('aria-label', 'Quiz results');

  // Score card
  let score = 0;
