/**
 * Final accessibility audit — reads the submitted index.html directly (inlined CSS+JS).
 */
const { chromium } = require('playwright');
const path = require('path');
const fs   = require('fs');

(async () => {
  const dir     = path.join(__dirname);
  const fullHtml = fs.readFileSync(path.join(dir, 'index.html'), 'utf8');

  const b = await chromium.launch();
  const page = await b.newPage();

  async function auditState(label) {
    await page.addScriptTag({ path: '/tmp/axe.min.js' });
    const r = await page.evaluate(async () => await window.axe.run());
    const wcag = r.violations.filter(v => !v.tags.includes('best-practice'));
    const bp   = r.violations.filter(v =>  v.tags.includes('best-practice'));
    return { label, wcag, bp };
  }

  // State 1: initial quiz
  await page.setContent(fullHtml, { waitUntil: 'networkidle' });
  await page.waitForSelector('.form-field');
  const state1 = await auditState('Initial quiz view');

  // State 2: submit with one answer per question → results
  await page.check('input[name="q1"][value="typescript"]');
  await page.check('input[name="q2"][value="c"]');
  await page.check('input[name="q3"][value="haskell"]');
  await page.click('button[type="submit"]');
  await page.waitForSelector('.results-score-card');
  const state2 = await auditState('Post-submit results view');

  // State 3: wrong answer (to exercise wrong-selected styling)
  await page.click('button.btn-retry');
  await page.waitForSelector('.form-field');
  await page.check('input[name="q1"][value="python"]');   // wrong
  await page.check('input[name="q2"][value="javascript"]'); // wrong
  await page.check('input[name="q3"][value="java"]');      // wrong
  await page.click('button[type="submit"]');
  await page.waitForSelector('.results-score-card');
  const state3 = await auditState('Post-submit with wrong answers');

  await b.close();

  const results = [state1, state2, state3];
  const totalWcag = results.reduce((n, s) => n + s.wcag.length, 0);

  console.log(JSON.stringify(results.map(s => ({
    state: s.label,
    wcag: s.wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) })),
    bp:   s.bp.map(v =>   ({ id: v.id, targets: v.nodes.map(n => n.target) })),
  })), null, 2));

  process.exit(totalWcag > 0 ? 1 : 0);
})();
TESTEOF
